      season: ps.season,
      faabBudget: faabBudgetOf(ps.leagueInfo?.settings?.waiver_budget),
      ownerByRoster,
      userById: Object.fromEntries(ps.users.map((u) => [u.user_id, u])),
      transactions: ps.transactions,
